import pandas as pd
import numpy as np

class VolumeAnalysisStrategy:
    def __init__(self, data):
        self.data = data
        self.indicators = self.calculate_indicators()
        self.entry_rules = self.define_entry_rules()
        self.exit_rules = self.define_exit_rules()
        self.risk_management = self.define_risk_management()

    def calculate_indicators(self):
        # Calculate Bollinger Bands
        self.data['SMA_20'] = self.data['Close'].rolling(window=20).mean()
        self.data['Upper_BB'] = self.data['SMA_20'] + 2 * self.data['Close'].rolling(window=20).std()
        self.data['Lower_BB'] = self.data['SMA_20'] - 2 * self.data['Close'].rolling(window=20).std()

        # Calculate ATR
        self.data['High_Low'] = self.data['High'] - self.data['Low']
        self.data['High_Close'] = np.abs(self.data['High'] - self.data['Close'].shift(1))
        self.data['Low_Close'] = np.abs(self.data['Low'] - self.data['Close'].shift(1))
        self.data['TR'] = self.data[['High_Low', 'High_Close', 'Low_Close']].max(axis=1)
        self.data['ATR'] = self.data['TR'].rolling(window=14).mean()

        # Calculate ADX
        self.data['Plus_DM'] = self.data['High'] - self.data['High'].shift(1)
        self.data['Minus_DM'] = self.data['Low'].shift(1) - self.data['Low']
        self.data['Plus_DM'] = np.where(self.data['Plus_DM'] > 0, self.data['Plus_DM'], 0)
        self.data['Minus_DM'] = np.where(self.data['Minus_DM'] > 0, self.data['Minus_DM'], 0)
        self.data['Plus_DI'] = self.data['Plus_DM'].rolling(window=14).mean() / self.data['ATR']
        self.data['Minus_DI'] = self.data['Minus_DM'].rolling(window=14).mean() / self.data['ATR']
        self.data['DX'] = np.abs(self.data['Plus_DI'] - self.data['Minus_DI']) / (self.data['Plus_DI'] + self.data['Minus_DI'])
        self.data['ADX'] = self.data['DX'].rolling(window=14).mean()

        return {
            'Bollinger_Bands': {
                'Upper': self.data['Upper_BB'],
                'Lower': self.data['Lower_BB']
            },
            'ATR': self.data['ATR'],
            'ADX': self.data['ADX']
        }

    def define_entry_rules(self):
        return {
            'long': [
                self.data['Close'] > self.indicators['Bollinger_Bands']['Upper'],
                self.indicators['ADX'] > 25,
                self.indicators['ATR'] < self.indicators['ATR'].rolling(window=5).mean()
            ],
            'short': [
                self.data['Close'] < self.indicators['Bollinger_Bands']['Lower'],
                self.indicators['ADX'] > 25,
                self.indicators['ATR'] < self.indicators['ATR'].rolling(window=5).mean()
            ]
        }

    def define_exit_rules(self):
        return {
            'long': [
                self.data['Close'] <= self.indicators['Bollinger_Bands']['Lower'],
                self.indicators['ADX'] < 20,
                self.data['Close'] * 0.98,
                self.data['Close'] * 1.05
            ],
            'short': [
                self.data['Close'] >= self.indicators['Bollinger_Bands']['Upper'],
                self.indicators['ADX'] < 20,
                self.data['Close'] * 1.02,
                self.data['Close'] * 0.95
            ]
        }

    def define_risk_management(self):
        return {
            'position_sizing': {
                'method': 'fixed_fraction',
                'fraction': 0.02
            },
            'stop_loss': 0.02,
            'take_profit': 0.05
        }

    def generate_signals(self):
        signals = pd.DataFrame(index=self.data.index)
        signals['long'] = np.where((self.entry_rules['long'][0]) & (self.entry_rules['long'][1]) & (self.entry_rules['long'][2]), 1, 0)
        signals['short'] = np.where((self.entry_rules['short'][0]) & (self.entry_rules['short'][1]) & (self.entry_rules['short'][2]), -1, 0)
        signals['long_exit'] = np.where((self.exit_rules['long'][0]) | (self.exit_rules['long'][1]), -1, 0)
        signals['short_exit'] = np.where((self.exit_rules['short'][0]) | (self.exit_rules['short'][1]), 1, 0)

        return signals

